'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

let pos = 0;
const N = Number(input[pos++]);
const M = Number(input[pos++]);
const grid = [];

for (let i = 0; i < N; i++) {
  grid.push(input[pos++].split(''));
}

const queue = [];
for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    if (grid[i][j] === 'o') queue.push(i * M + j);
  }
}

for (let head = 0; head < queue.length; head++) {
  const cell = queue[head];
  const i = Math.floor(cell / M);
  const j = cell % M;

  if (i + 1 < N && grid[i + 1][j] === '.') {
    grid[i + 1][j] = 'o';
    queue.push((i + 1) * M + j);
  }

  if (i + 1 < N && grid[i + 1][j] === '#') {
    if (j > 0 && grid[i][j - 1] === '.') {
      grid[i][j - 1] = 'o';
      queue.push(i * M + j - 1);
    }
    if (j + 1 < M && grid[i][j + 1] === '.') {
      grid[i][j + 1] = 'o';
      queue.push(i * M + j + 1);
    }
  }
}

process.stdout.write(grid.map(row => row.join('')).join('\n'));
